// Reads the table generated by the Qiskit code (qollab/main.py --export). The game never re-implements the gate rules.
import table from '../qollab/data/weapon_table.json';

const CODES = { mirror: 'M', shotgun: 'S', phantom: 'P', link: 'L' };
export const MAX_QUANTUM_CARDS = table.max_cards;

export const buildKey = (cards) => cards.map((c) => CODES[c]).join(',');
export const lookup = (cards) => table.builds[buildKey(cards)];

// Firing = measuring: pick a sector with the probabilities computed by Qiskit.
export function sampleSector(probs) {
  let r = Math.random();
  for (let k = 0; k < probs.length; k++) {
    r -= probs[k];
    if (r <= 0) return k;
  }
  return probs.findIndex((p) => p > 0);
}
